module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    parameter s0 = 0;
    parameter s1 = 1;
    parameter s2 = 2;
    parameter s3 = 3;

    reg [1:0] pulse_level1;
    reg [1:0] pulse_level2;

    // Combinational logic for data_out
    always @(*) begin
        if (!rst_n)
            data_out = 0;
        else if (pulse_level2 == s2 && data_in == 0)
            data_out = 1;
        else
            data_out = 0;
    end

    // Sequential logic for pulse_level1
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pulse_level1 <= s0;
        else
            pulse_level1 <= pulse_level2;
    end

    // Combinational logic for pulse_level2
    always @(*) begin
        case (pulse_level1)
            s0: if (data_in == 0) pulse_level2 = s1; else pulse_level2 = s0;
            s1: if (data_in == 1) pulse_level2 = s2; else pulse_level2 = s1;
            s2: if (data_in == 0) pulse_level2 = s3; else pulse_level2 = s0;
            s3: if (data_in == 1) pulse_level2 = s2; else pulse_level2 = s1;
            default: pulse_level2 = s0;
        endcase
    end

endmodule
